ST.xhtml:p:
R_Trigger1(CLK := g_biSustain1Abs OR bSustain1Abs OR g_bSustain1Abs OR g_bSustainAxis1AbsMoveEnableM);
R_Trigger2(CLK := g_biSustain2Abs OR bSustain2Abs OR g_bSustain2Abs OR g_bSustainAxis2AbsMoveEnableM);
R_Trigger3(CLK := g_biSustain3Abs OR bSustain3Abs OR g_bSustain3Abs OR g_bSustainAxis3AbsMoveEnableM);
R_Trigger7(CLK := g_biSustain7Abs OR bSustain7Abs OR g_bSustain7Abs OR g_bSustainAxis4AbsMoveEnableM);
R_Trigger8(CLK := g_biSustain8Abs OR bSustain8Abs OR g_bSustain8Abs OR g_bSustainAxis5AbsMoveEnableM);
R_Trigger9(CLK := g_biSustain9Abs OR bSustain9Abs OR g_bSustain9Abs OR g_bSustainAxis6AbsMoveEnableM);
R_Trigger10(CLK := g_bAxisStopFlag);
R_Trigger11(CLK := g_bAxisStopFlag_5 OR g_bAxisStopFlag_6 OR g_bAxisStopFlag_7 OR g_bAxisStopFlag_8 OR g_bAxisStopFlag_9 OR g_bAxisStopFlag_10);

IF R_Trigger1.Q THEN
  nState1 := 1;
  bSustain1AbsDone := FALSE;
  g_bSustain1AbsDone := FALSE;
  dSustainAxis1AbsMoveSpeed := dSustain1TargetVel;
  IF g_biSustain1Abs THEN
    nState1 := 0;
  ELSIF g_bSustain1Abs THEN(*PLC内部触发，浮动或者M代码触发*)
    dSustain1TargetPos := g_bSustain1AbsPosition;
    g_bSustain1Abs := FALSE;
  ELSIF bSustain1Abs THEN
    dSustain1TargetPos := dSustain1Position;
    bSustain1Abs := FALSE;
    IF g_bPowerOffMoveToTargetPosSetSpeedFlag THEN
      dSustainAxis1AbsMoveSpeed := g_dPowerOffMoveToTargetPosSpeed;
    END_IF;
  ELSIF g_bSustainAxis1AbsMoveEnableM THEN
    g_bSustainAxis1AbsMoveEnableM := FALSE;
    dSustain1TargetPos := g_dSustainAxisMoveDistanceM; 
    IF g_bSetAuxiliaryAxisSpeed THEN
      dSustainAxis1AbsMoveSpeed := g_nAuxiliaryAxisSpeed;
      g_bSetAuxiliaryAxisSpeed := FALSE;
    END_IF;
    IF g_fCurrentCoordYBuffer >= (g_fSupAxisCoordY1 - g_fSupAxisDownDis1) THEN
       bSustain1AbsDone := TRUE;
      g_bSustain1AbsDone := TRUE;
      g_bSustainAxis1MoveDoneM320 := TRUE;
      nState1 := 0;
      g_bExecuteFinishedM306 := FALSE;
      g_bFinishedM306_1 := FALSE;
    END_IF;
  END_IF;
  IF g_nAntiRejectionFun=1 THEN(*当界面或者M代码触发时左右防甩气缸也松开，浮动触发的忽略*)
    IF g_bSupportAxisMoveLossenAntiCyl1 THEN
      IF g_nAntiRejectionCylNum>=1 AND g_bAntiRejectionCylLoosenDone1=FALSE THEN
        g_bCylAntiRejectionClose1:=TRUE;
      END_IF;
    END_IF;
  END_IF;

  (*IF nState1 <> 0 AND nState1 <> 20 AND Axis_Sustain1.NCTOPLC.ACTVELO > g_dCheckAxisIsMovingSpeedSet THEN
    g_bAxisIsMoveAlarm := TRUE;
    bSustain1Abs := FALSE;
    g_bSustain1Abs := FALSE;
    g_bSustainAxis1AbsMoveEnableM := FALSE;
	nState1 := 21;
  END_IF;*)
  g_bSupportAxisMoveLossenAntiCyl1:=FALSE;
END_IF;

