IF R_Trigger10.Q THEN
  IF g_nAxisStopP = 5 THEN
    g_bAxisStopFlag := FALSE;
    nState1 := 21;
  ELSIF g_nAxisStopP = 6 THEN
    g_bAxisStopFlag := FALSE;
    nState2 := 21;
  ELSIF g_nAxisStopP = 7 THEN
    g_bAxisStopFlag := FALSE;
    nState3 := 21;
  ELSIF g_nAxisStopP = 8 THEN
    g_bAxisStopFlag := FALSE;
    nState7 := 21;
  ELSIF g_nAxisStopP = 9 THEN
    g_bAxisStopFlag := FALSE;
    nState8 := 21;
  ELSIF g_nAxisStopP = 10 THEN
    g_bAxisStopFlag := FALSE;
    nState9 := 21;
  END_IF;
END_IF;

IF R_Trigger11.Q THEN
  IF g_bAxisStopFlag_5 THEN
    g_bAxisStopFlag_5 := FALSE;
    nState1 := 21;
  END_IF;
  IF g_bAxisStopFlag_6 THEN
    g_bAxisStopFlag_6 := FALSE;
    nState2 := 21;
  END_IF;
  IF g_bAxisStopFlag_7 THEN
    g_bAxisStopFlag_7 := FALSE;
    nState3 := 21;
  END_IF;
  IF g_bAxisStopFlag_8 THEN
    g_bAxisStopFlag_8 := FALSE;
    nState7 := 21;
  END_IF;
  IF g_bAxisStopFlag_9 THEN
    g_bAxisStopFlag_9 := FALSE;
    nState8 := 21;
  END_IF;
  IF g_bAxisStopFlag_10 THEN
    g_bAxisStopFlag_10 := FALSE;
    nState9 := 21;
  END_IF;
END_IF;

CASE nState1 OF
  0:
    nState1 := 0;
  1:
    g_Sustain1Abs.Execute := TRUE;
    g_Sustain1Abs.Velocity := dSustainAxis1AbsMoveSpeed;
    g_Sustain1Abs.Position := dSustain1TargetPos;
    IF g_Sustain1Abs.Done THEN
      g_Sustain1Abs.Execute := FALSE;
      bSustain1AbsDone := TRUE;
      g_bSustain1AbsDone := TRUE;
      g_bSustainAxis1MoveDoneM320 := TRUE;
      nState1 := 0;
      g_bExecuteFinishedM306 := FALSE;
      g_bFinishedM306_1 := FALSE;
    END_IF;    
    IF g_bPlcPauseBuffer THEN
      nState1 := 20;
    END_IF;
    IF g_Sustain1Abs.CommandAborted OR g_Sustain1Abs.Error THEN
      g_Sustain1Abs.Execute := FALSE;
      nState1 := 0;
      M.ENABLE[306] := 0;
      g_bExecuteFinishedM306 := FALSE;
      g_bFinishedM306_1 := FALSE;
    END_IF;
  20:
    g_Sustain1Abs.Execute := FALSE;
    g_Sustain1Stop.Execute := TRUE;
    IF g_Sustain1Stop.Done AND g_bPlcStartBuffer THEN
      g_Sustain1Stop.Execute := FALSE;
      nState1 := 1;
    END_IF;
    IF g_Sustain1Stop.CommandAborted OR g_Sustain1Stop.Error THEN
      g_Sustain1Stop.Execute := FALSE;
      nState1 := 0;
      M.ENABLE[306] := 0;
      g_bExecuteFinishedM306 := FALSE;
      g_bFinishedM306_1 := FALSE;
    END_IF;
  21:
    g_Sustain1Abs.Execute := FALSE;
    g_Sustain1Stop.Execute := TRUE;
    IF g_Sustain1Stop.Done THEN
      g_Sustain1Stop.Execute := FALSE;
      g_bFinishedM325_5 := FALSE;
      M.ENABLE[325] := 0;
      nState1 := 0;
      g_bSustainAxis1MoveDoneM320 := TRUE;
    END_IF;
    IF g_Sustain1Stop.CommandAborted OR g_Sustain1Stop.Error THEN
      g_Sustain1Stop.Execute := FALSE;
      g_bFinishedM325_5 := FALSE;
      M.ENABLE[325] := 0;
      nState1 := 0;
      M.ENABLE[306] := 0;
      g_bExecuteFinishedM306 := FALSE;
      g_bFinishedM306_1 := FALSE;
    END_IF;
END_CASE;

